import { useRef } from 'react';

export default function Counter() {
  const ref = useRef(0);

  function handleClick() {
    ref.current += 1;
    alert('클릭한 횟수: ' + ref.current + '회!');
  }

  return (
    <button onClick={handleClick}>클릭하세요!</button>
  );
}
